package tokenizer

import java.time.{LocalDate, LocalDateTime, format}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import scala.util.{Try, Success, Failure}
import io.circe.{Json, ParsingFailure}
import io.circe.parser._

// ============================================================================
// Protocols (Traits)
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(kwargs: (String, Any)*): Token = {
    copy(metadata = this.metadata ++ kwargs.toMap)
  }
}

class MutableTokenBatch {
  private val _tokens = mutable.ListBuffer[Token]()
  private var _processed = false

  def tokens: List[Token] = _tokens.toList

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Seq[T] = items

  def getAll: Seq[T] = _items

  def size: Int = _items.size

  def mapTokens(func: T => String): Seq[String] = {
    _items.map(func)
  }
}

class TokenSink[-T] {
  private val _received = mutable.ListBuffer[Any]()

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

class BivariantHandler[T](default: T) {
  private var _value: T = default

  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

class StringTokenizer(
  encoding: String = "utf-8",
  normalizer: Option[String => String] = None
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  private val _normalizer = normalizer.getOrElse((x: String) => x)

  // Convenience for direct String usage
  def tokenize(value: String): Token = tokenize(Left(value))

  override def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Right(bytes) => new String(bytes, encoding)
      case Left(s) => s
    }

    val normalized = _normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }
}

class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] { // Using Any to cover Int, Double, BigDecimal like generic NumericT

  override def tokenize(value: Any): Token = {
    val (strValue, originalType) = value match {
      case d: BigDecimal => 
        (f"$d%.${precision}f", "Decimal") // Scala BigDecimal
      case f: Double =>
        (f"$f%.${precision}f", "float")
      case f: Float =>
        (f"$f%.${precision}f", "float")
      case i: Int =>
        (i.toString, "int")
      case l: Long =>
        (l.toString, "int")
      case n: Number =>
        (n.toString, n.getClass.getSimpleName)
      case other =>
        (other.toString, other.getClass.getSimpleName)
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }
}

class TemporalTokenizer(formatStr: Option[String] = None) 
  extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {

  private val IsoFormat = DateTimeFormatter.ISO_LOCAL_DATE_TIME
  private val DateFormat = DateTimeFormatter.ISO_LOCAL_DATE

  // Overloads for convenience
  def tokenize(value: LocalDateTime): Token = tokenize(Left(value))
  def tokenize(value: LocalDate): Token = tokenize(Right(value))

  override def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val formatter = formatStr.map(DateTimeFormatter.ofPattern).getOrElse {
      value match {
        case Left(_) => IsoFormat
        case Right(_) => DateFormat
      }
    }

    val strValue = value match {
      case Left(dt) => dt.format(formatter)
      case Right(d) => d.format(formatter)
    }

    Token(strValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Advanced: Union Types and Overloads
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: String): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Array[Byte]): Token = stringTokenizer.tokenize(Right(value))
  def tokenize(value: Int): Token = numericTokenizer.tokenize(value)
  def tokenize(value: Double): Token = numericTokenizer.tokenize(value)
  def tokenize(value: BigDecimal): Token = numericTokenizer.tokenize(value)
  def tokenize(value: LocalDateTime): Token = temporalTokenizer.tokenize(value)
  def tokenize(value: LocalDate): Token = temporalTokenizer.tokenize(value)

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Tokenizable): Token = Token(value.toToken, TokenType.STRUCTURED)

